import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, DirectionalLight, Color } = ctx.THREE;

  // Root object for this node
  const root = new Group();
  root.name = config?.name || 'stat-tile-collection';

  // Store references for cleanup
  const primitiveInstances = [];
  const timelineDisposers = [];

  // -----------------------------------------------------------------------
  // Load GLB mesh (synchronous return, asynchronous load handling)
  // -----------------------------------------------------------------------
  ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
    const loaded = gltf.scene || gltf;
    root.add(loaded);

    // Ensure meshes cast/receive shadows
    loaded.traverse((obj) => {
      if (obj.isMesh) {
        obj.castShadow = true;
        obj.receiveShadow = true;
      }
    });

    // ---------------------------------------------------------------------
    // Weighted‑settle entrance animation (overshoot 1.04 → 1.0)
    // ---------------------------------------------------------------------
    const enterTl = gsap.timeline({ paused: false });
    enterTl
      .from(
        root.scale,
        {
          x: 0.96,
          y: 0.96,
          z: 0.96,
          duration: 0.9,
          ease: 'power4.out',
          immediateRender: false,
        },
        0,
      )
      .to(
        root.scale,
        {
          x: 1.04,
          y: 1.04,
          z: 1.04,
          duration: 0.1,
          ease: 'none',
        },
        '+=0',
      )
      .to(
        root.scale,
        {
          x: 1,
          y: 1,
          z: 1,
          duration: 0.3,
          ease: 'power4.out',
        },
        '+=0',
      );

    timelineDisposers.push(() => enterTl.kill());
  });

  // -----------------------------------------------------------------------
  // Accent rim light (machined‑metal highlight)
  // -----------------------------------------------------------------------
  const accentColor = (config.colors && config.colors.accent) || '#ff2a38';
  const rimLight = new DirectionalLight(new Color(accentColor), 0.6);
  rimLight.position.set(0, 0, 1);
  root.add(rimLight);

  // -----------------------------------------------------------------------
  // Interaction handlers (hover rise‑in, click emit)
  // -----------------------------------------------------------------------
  const hoverIn = () => {
    gsap.to(root.position, {
      y: '+=0.15',
      duration: 0.3,
      ease: 'power3.out',
    });
  };
  const hoverOut = () => {
    gsap.to(root.position, {
      y: '-=0.15',
      duration: 0.3,
      ease: 'power3.out',
    });
  };
  const click = () => {
    ctx.emit('hub-collection.select', {});
  };

  root.userData.handlers = {
    hover: hoverIn,
    hoverout: hoverOut,
    click,
  };

  // -----------------------------------------------------------------------
  // Apply cinematic primitives defined in the config
  // -----------------------------------------------------------------------
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (typeof fn === 'function') {
        const instance = fn(root, prim.params || {});
        primitiveInstances.push(instance);
      }
    }
  }

  // -----------------------------------------------------------------------
  // Cleanup routine
  // -----------------------------------------------------------------------
  root.userData.cleanup = () => {
    // Dispose geometries and materials from loaded meshes
    root.traverse((obj) => {
      if (obj.isMesh) {
        if (obj.geometry) obj.geometry.dispose();
        if (obj.material) {
          if (Array.isArray(obj.material)) {
            obj.material.forEach((m) => m.dispose && m.dispose());
          } else {
            obj.material.dispose && obj.material.dispose();
          }
        }
      }
    });

    // Kill GSAP timelines/tweens
    timelineDisposers.forEach((fn) => fn && fn());
    gsap.killTweensOf(root);

    // Cleanup primitives
    primitiveInstances.forEach((inst) => {
      if (inst && typeof inst.cleanup === 'function') inst.cleanup();
    });
  };

  return root;
}
